package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct {
	DrItem string
	DrPrice decimal.Decimal
	DrPct int64
}

var WsEofFlag string = "N"
var WsDiscount decimal.Decimal = decimal.NewFromInt(0)
var WsNet decimal.Decimal = decimal.NewFromInt(0)
var WsTotalNet decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsPriceEd string
var WsDiscEd string
var WsNetEd string
var WsTotalEd string

var discRec DiscRec

var InputDone bool = false

var discLines []string
var discIdx int
var discFile *os.File

func isInputDone() bool { return InputDone }

func store95V99(d decimal.Decimal) decimal.Decimal {
	t := d.Truncate(2)
	c := t.Shift(2).IntPart()
	m := int64(10000000)
	c = c % m
	return decimal.New(c, -2)
}

func store98V99(d decimal.Decimal) decimal.Decimal {
	t := d.Truncate(2)
	c := t.Shift(2).IntPart()
	m := int64(10000000000)
	c = c % m
	return decimal.New(c, -2)
}

func formatEdited(v decimal.Decimal, picture string) string {
	// split picture at '.'
	dot := strings.Index(picture, ".")
	var left, right string
	var scale int
	if dot >= 0 {
		left = picture[:dot]
		right = picture[dot+1:]
		scale = len(right)
	} else {
		left = picture
		right = ""
		scale = 0
	}
	// count integer digit positions
	nInt := 0
	for _, ch := range left {
		if ch == 'Z' || ch == '9' {
			nInt++
		}
	}
	// truncate toward zero to scale
	t := v.Truncate(int32(scale))
	neg := t.IsNegative()
	if neg {
		t = t.Neg()
	}
	// integer and fraction parts
	pow10 := decimal.NewFromInt(1)
	for i := 0; i < scale; i++ {
		pow10 = pow10.Mul(decimal.NewFromInt(10))
	}
	// get scaled integer cents
	scaled := t.Shift(int32(scale)).Truncate(0)
	scaledInt := scaled.IntPart()
	var intVal, fracVal int64
	if scale > 0 {
		p := pow10.IntPart()
		intVal = scaledInt / p
		fracVal = scaledInt % p
	} else {
		intVal = scaledInt
		fracVal = 0
	}
	// drop high-order digits
	mod := int64(1)
	for i := 0; i < nInt; i++ {
		mod *= 10
	}
	if nInt > 0 {
		intVal = intVal % mod
	}
	// digits zero padded
	digits := make([]byte, nInt)
	tmp := intVal
	for i := nInt - 1; i >= 0; i-- {
		digits[i] = byte(tmp % 10)
		tmp /= 10
	}
	// find first nonzero
	firstNZ := -1
	for i, d := range digits {
		if d != 0 {
			firstNZ = i
			break
		}
	}
	// map left picture
	var sb strings.Builder
	di := 0
	// need to know digit index for commas: count digits left of each point
	// For comma at position, check if any nonzero digit to the left
	for _, ch := range left {
		switch ch {
		case 'Z':
			d := digits[di]
			di++
			if firstNZ == -1 || (di-1) < firstNZ {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte('0' + d)
			}
		case '9':
			d := digits[di]
			di++
			sb.WriteByte('0' + d)
		case ',':
			// digits consumed so far = di; remaining? if firstNZ == -1 => space; else if firstNZ < di => there is nonzero to left? Actually need nonzero strictly left of comma
			hasLeft := false
			if firstNZ != -1 && firstNZ < di {
				hasLeft = true
			}
			if hasLeft {
				sb.WriteByte(',')
			} else {
				sb.WriteByte(' ')
			}
		default:
			sb.WriteByte(byte(ch))
		}
	}
	if dot >= 0 {
		sb.WriteByte('.')
		// fraction digits zero padded to scale
		fr := make([]byte, scale)
		tmp2 := fracVal
		for i := scale - 1; i >= 0; i-- {
			fr[i] = byte(tmp2 % 10)
			tmp2 /= 10
		}
		for _, b := range fr {
			sb.WriteByte('0' + b)
		}
	}
	s := sb.String()
	_ = neg
	return s
}

func formatCount(c int64) string {
	v := c % 1000
	if v < 0 {
		v += 1000
	}
	return fmt.Sprintf("%03d", v)
}

func formatPct(p int64) string {
	v := p % 100
	if v < 0 {
		v += 100
	}
	return fmt.Sprintf("%02d", v)
}

func parsePrice(s string) decimal.Decimal {
	if strings.Trim(s, " ") == "" {
		return decimal.NewFromInt(0)
	}
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.NewFromInt(0)
	}
	// keep digits and optional sign
	neg := false
	if strings.HasPrefix(t, "-") {
		neg = true
		t = t[1:]
	} else if strings.HasPrefix(t, "+") {
		t = t[1:]
	}
	// remove spaces inside?
	t = strings.ReplaceAll(t, " ", "")
	if t == "" {
		return decimal.NewFromInt(0)
	}
	var n int64
	for _, ch := range t {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
		}
	}
	d := decimal.New(n, -2)
	if neg {
		d = d.Neg()
	}
	return d
}

func parsePct(s string) int64 {
	if strings.Trim(s, " ") == "" {
		return 0
	}
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	neg := false
	if strings.HasPrefix(t, "-") {
		neg = true
		t = t[1:]
	} else if strings.HasPrefix(t, "+") {
		t = t[1:]
	}
	t = strings.ReplaceAll(t, " ", "")
	if t == "" {
		return 0
	}
	var n int64
	for _, ch := range t {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
		}
	}
	if neg {
		n = -n
	}
	// keep low-order 2 digits (COBOL move truncation)? record field already limited
	n = n % 100
	if n < 0 {
		// keep sign? high-order dropped keeps sign with low digits
		// Go % keeps sign, fine
	}
	return n
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty? COBOL would error; exit non-zero
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	// read all lines preserving spaces (strip only \n and \r)
	sc := bufio.NewScanner(f)
	// allow long lines
	sc.Buffer(make([]byte, 1024*1024), 1024*1024)
	for sc.Scan() {
		line := sc.Text()
		if strings.HasSuffix(line, "\r") {
			// Scanner strips \n but keeps \r? Actually Text strips \n and \r? For ScanLines it strips \r\n. Keep as is.
		}
		discLines = append(discLines, line)
	}
	f.Close()
	discIdx = 0
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	SummaryPara()
}

func ReadPara() {
	if discIdx >= len(discLines) {
		InputDone = true
		WsEofFlag = "Y"
		return
	}
	line := discLines[discIdx]
	discIdx++
	// pad with spaces to 15 on right, truncate to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	item := line[0:6]
	priceStr := line[6:13]
	pctStr := line[13:15]
	discRec.DrItem = item
	discRec.DrPrice = parsePrice(priceStr)
	// DR-PRICE stored as 9(5)V99: truncate/mod already fits since 7 digits, but apply store?
	discRec.DrPrice = store95V99(discRec.DrPrice.Truncate(2))
	discRec.DrPct = parsePct(pctStr)
}

func ProcessPara() {
	raw := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct)).Shift(-2)
	rounded := raw.Round(2)
	WsDiscount = store95V99(rounded)
	WsNet = store95V99(discRec.DrPrice.Sub(WsDiscount).Truncate(2))
	WsTotalNet = store98V99(WsTotalNet.Add(WsNet).Truncate(2))
	WsCount = (WsCount + 1) % 1000
	WsPriceEd = formatEdited(discRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")
	fmt.Println(padRight(discRec.DrItem, 6)+" "+WsPriceEd+" "+formatPct(discRec.DrPct)+"% "+WsDiscEd+" "+WsNetEd)
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	fmt.Println("ITEMS: "+formatCount(WsCount)+" NET TOTAL: "+WsTotalEd)
}

func main() {
	_ = discFile
	MainPara()
}
